body=body.replace('{draft}',''.join('<span>'+html.escape(x)+'</span>' for x in '帮我整理下一次发布的计划。'))
captions=[('收起会话列表，常用入口仍在','Collapse the list. Keep your Dock.'),('常用功能，按你的习惯摆放','Choose and reorder your Dock.'),('置顶只显示一次，取消即回原组','Pin once. Unpin to return to the workspace.'),('一个开关，恢复已有工具内容','One toggle. Restore your existing tools.'),('在右侧直接播放、拖动进度','Play and seek videos in the side panel.'),('先写草稿，发送时才创建会话','Draft first. Create a chat when you send.')]
